tool_schemas.implementation:
def search_pubchem_by_name(name, max_results=None, **_extra):
    import json, os, datetime, time, hashlib, urllib.parse, urllib.request

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0145000" if __import__("os").path.isdir("./environment_mix/0145000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        try:
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + ':' + str(time.time_ns())).encode('utf-8')).hexdigest()[:24]}"

    def _norm_str(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        t = s.strip()
        return t

    def _clamp_max_results(v):
        if v is None:
            v = 5
        if not isinstance(v, int):
            return None, _err("VALIDATION_ERROR", "max_results must be an integer between 1 and 100.")
        if v < 1 or v > 100:
            return None, _err("VALIDATION_ERROR", "max_results must be between 1 and 100.")
        return v, None

    def _resolve_active_key():
        keys = _load("api_keys.json")
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None
        # pick the one with highest remaining limits (best chance to serve)
        def score(k):
            d = k.get("daily_request_limit")
            m = k.get("per_minute_limit")
            return (d if isinstance(d, int) else -1, m if isinstance(m, int) else -1)
        active.sort(key=score, reverse=True)
        return active[0]

    def _window_starts(now):
        day_start = now.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)
        minute_start = now.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0)
        return day_start, minute_start

    def _get_or_create_counter(counters, api_key_id, window_type, window_start, now):
        ws = _iso(window_start)
        for c in counters:
            if c.get("api_key_id") == api_key_id and c.get("window_type") == window_type and c.get("window_start") == ws:
                return c
        row = {
            "id": _new_id("uc"),
            "api_key_id": api_key_id,
            "window_type": window_type,
            "window_start": ws,
            "request_count": 0,
            "succeeded_count": 0,
            "failed_count": 0,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        counters.append(row)
        return row

    def _enforce_limits(api_key_row, now):
        if api_key_row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active.")
        daily_limit = api_key_row.get("daily_request_limit")
        per_min_limit = api_key_row.get("per_minute_limit")
        if not isinstance(daily_limit, int) or daily_limit < 0:
            return _err("VALIDATION_ERROR", "API key has invalid daily_request_limit.")
        if not isinstance(per_min_limit, int) or per_min_limit < 0:
            return _err("VALIDATION_ERROR", "API key has invalid per_minute_limit.")

        counters = _load("usage_counters.json")
        day_start, minute_start = _window_starts(now)
        day_c = _get_or_create_counter(counters, api_key_row["id"], "day", day_start, now)
        min_c = _get_or_create_counter(counters, api_key_row["id"], "minute", minute_start, now)

        # Reject if this request would exceed limits (i.e., current count already at limit)
        if per_min_limit == 0:
            _save("usage_counters.json", counters)
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded.")
        if daily_limit == 0:
            _save("usage_counters.json", counters)
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        if isinstance(min_c.get("request_count"), int) and min_c["request_count"] >= per_min_limit:
            _save("usage_counters.json", counters)
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded.")
        if isinstance(day_c.get("request_count"), int) and day_c["request_count"] >= daily_limit:
            _save("usage_counters.json", counters)
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

        # pre-increment request_count (counts all attempts)
        for c in (day_c, min_c):
            c["request_count"] = int(c.get("request_count") or 0) + 1
            c["updated_at"] = _iso(now)
        _save("usage_counters.json", counters)
        return None

    def _bump_success_failure(api_key_id, now, succeeded):
        counters = _load("usage_counters.json")
        day_start, minute_start = _window_starts(now)
        day_ws = _iso(day_start)
        min_ws = _iso(minute_start)
        for c in counters:
            if c.get("api_key_id") != api_key_id:
                continue
            if c.get("window_type") == "day" and c.get("window_start") == day_ws:
                if succeeded:
                    c["succeeded_count"] = int(c.get("succeeded_count") or 0) + 1
                else:
                    c["failed_count"] = int(c.get("failed_count") or 0) + 1
                c["updated_at"] = _iso(now)
            if c.get("window_type") == "minute" and c.get("window_start") == min_ws:
                if succeeded:
                    c["succeeded_count"] = int(c.get("succeeded_count") or 0) + 1
                else:
                    c["failed_count"] = int(c.get("failed_count") or 0) + 1
                c["updated_at"] = _iso(now)
        _save("usage_counters.json", counters)

    def _fingerprint(tool, params):
        # stable ordering
        b = json.dumps({"tool": tool, **params}, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(b.encode("utf-8")).hexdigest()

    def _today_date_str(now):
        return now.astimezone(datetime.timezone.utc).date().isoformat()

    def _same_utc_date(dt, now):
        ddt = _parse_dt(dt)
        if not ddt:
            return False
        return ddt.astimezone(datetime.timezone.utc).date() == now.astimezone(datetime.timezone.utc).date()

    def _find_cached_request(api_key_id, tool_name, fingerprint, now):
        reqs = _load("search_requests.json")
        candidates = []
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            if r.get("tool_name") != tool_name:
                continue
            if r.get("request_fingerprint") != fingerprint:
                continue
            if not _same_utc_date(r.get("created_at"), now):
                continue
            if r.get("status") == "succeeded":
                candidates.append(r)
        # choose latest by created_at
        def keyfn(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return dt
        candidates.sort(key=keyfn, reverse=True)
        return candidates[0] if candidates else None

    def _get_results_for_request(req_id):
        results = _load("search_results.json")
        compounds = _load("compounds.json")
        comp_by_id = {c.get("id"): c for c in compounds if isinstance(c, dict) and isinstance(c.get("id"), str)}
        rows = []
        for sr in results:
            if not isinstance(sr, dict):
                continue
            if sr.get("search_request_id") != req_id:
                continue
            c = comp_by_id.get(sr.get("compound_id"))
            if c:
                rows.append((sr, c))
        rows.sort(key=lambda t: int(t[0].get("rank") or 0))
        return rows

    def _normalize_compound(c):
        return {
            "cid": c.get("pubchem_cid"),
            "canonical_smiles": c.get("canonical_smiles"),
            "isomeric_smiles": c.get("isomeric_smiles"),
            "inchi": c.get("inchi"),
            "inchi_key": c.get("inchi_key"),
            "molecular_formula": c.get("molecular_formula"),
            "molecular_weight": c.get("molecular_weight"),
            "iupac_name": c.get("iupac_name"),
            "synonyms": c.get("synonyms") if isinstance(c.get("synonyms"), list) else None,
            "source_url": c.get("source_url"),
            "cached_at": c.get("cached_at"),
            "cache_status": c.get("cache_status"),
        }

    def _update_key_last_used(api_key_id, now):
        keys = _load("api_keys.json")
        changed = False
        for k in keys:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                changed = True
                break
        if changed:
            _save("api_keys.json", keys)

    # -------------------- validation --------------------
    start = time.time()
    now = _now_utc()

    nm = _norm_str(name)
    if nm is None:
        return _err("VALIDATION_ERROR", "name must be a string.")
    if nm == "":
        return _err("VALIDATION_ERROR", "name must be non-empty.")

    mr, e = _clamp_max_results(max_results)
    if e:
        return e

    api_key = _resolve_active_key()
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    tool_name = "search_pubchem_by_name"
    fp = _fingerprint(tool_name, {"name": nm, "max_results": mr})

    # -------------------- rate limit (counts attempt) --------------------
    limit_err = _enforce_limits(api_key, now)
    if limit_err:
        # log failed request (no external)
        reqs = _load("search_requests.json")
        req_id = _new_id("sr")
        dur_ms = int((time.time() - start) * 1000)
        reqs.append({
            "id": req_id,
            "api_key_id": api_key["id"],
            "tool_name": tool_name,
            "name": nm,
            "smiles": None,
            "formula": None,
            "cid": None,
            "max_results": mr,
            "status": "failed",
            "http_status_code": None,
            "error_message": limit_err["error"]["message"],
            "request_fingerprint": fp,
            "served_from_cache": True,
            "result_count": 0,
            "duration_ms": dur_ms,
            "created_at": _iso(now),
            "updated_at": _iso(_now_utc()),
        })
        _save("search_requests.json", reqs)
        _bump_success_failure(api_key["id"], _now_utc(), succeeded=False)
        return limit_err

    # -------------------- caching --------------------
    cached = _find_cached_request(api_key["id"], tool_name, fp, now)
    if cached:
        rows = _get_results_for_request(cached["id"])
        out = []
        for sr, comp in rows[:mr]:
            out.append(_normalize_compound(comp))
        dur_ms = int((time.time() - start) * 1000)

        # log a new request served from cache (queued->running->succeeded)
        reqs = _load("search_requests.json")
        req_id = _new_id("sr")
        created = _now_utc()
        req_row = {
            "id": req_id,
            "api_key_id": api_key["id"],
            "tool_name": tool_name,
            "name": nm,
            "smiles": None,
            "formula": None,
            "cid": None,
            "max_results": mr,
            "status": "queued",
            "http_status_code": None,
            "error_message": None,
            "request_fingerprint": fp,
            "served_from_cache": True,
            "result_count": len(out),
            "duration_ms": None,
            "created_at": _iso(created),
            "updated_at": _iso(created),
        }
        reqs.append(req_row)
        _save("search_requests.json", reqs)

        # transitions: queued -> running -> succeeded
        reqs = _load("search_requests.json")
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "running"
                r["updated_at"] = _iso(_now_utc())
                break
        _save("search_requests.json", reqs)

        reqs = _load("search_requests.json")
        finished = _now_utc()
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "succeeded"
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(finished)
                r["result_count"] = len(out)
                break
        _save("search_requests.json", reqs)

        # persist search_results rows for this new request too (as required)
        sres = _load("search_results.json")
        now2 = _now_utc()
        # map cached ranks/compounds
        cached_pairs = _get_results_for_request(cached["id"])[:len(out)]
        rank = 1
        for _sr, comp in cached_pairs:
            sres.append({
                "id": _new_id("res"),
                "search_request_id": req_id,
                "compound_id": comp.get("id"),
                "rank": rank,
                "match_type": "name",
                "score": None,
                "created_at": _iso(now2),
                "updated_at": _iso(now2),
            })
            rank += 1
        _save("search_results.json", sres)

        _bump_success_failure(api_key["id"], _now_utc(), succeeded=True)
        _update_key_last_used(api_key["id"], _now_utc())
        return {
            "search_request_id": req_id,
            "served_from_cache": True,
            "result_count": len(out),
            "results": out,
        }

    # -------------------- create request (queued) --------------------
    reqs = _load("search_requests.json")
    req_id = _new_id("sr")
    created = _now_utc()
    req_row = {
        "id": req_id,
        "api_key_id": api_key["id"],
        "tool_name": tool_name,
        "name": nm,
        "smiles": None,
        "formula": None,
        "cid": None,
        "max_results": mr,
        "status": "queued",
        "http_status_code": None,
        "error_message": None,
        "request_fingerprint": fp,
        "served_from_cache": False,
        "result_count": 0,
        "duration_ms": None,
        "created_at": _iso(created),
        "updated_at": _iso(created),
    }
    reqs.append(req_row)
    _save("search_requests.json", reqs)

    # transition to running
    reqs = _load("search_requests.json")
    for r in reqs:
        if r.get("id") == req_id:
            if r.get("status") != "queued":
                return _err("INVALID_TRANSITION", "search_request status must start as queued.")
            r["status"] = "running"
            r["updated_at"] = _iso(_now_utc())
            break
    _save("search_requests.json", reqs)

    # -------------------- outbound PubChem call --------------------
    try:
        base = "https://pubchem.ncbi.nlm.nih.gov/rest/pug"
        # name -> cids
        url_cids = f"{base}/compound/name/{urllib.parse.quote(nm)}/cids/JSON"
        req = urllib.request.Request(url_cids, headers={"User-Agent": "pubchem-mcp-offline/1.0"})
        with urllib.request.urlopen(req, timeout=15) as resp:
            http_code = getattr(resp, "status", None)
            body = resp.read().decode("utf-8", errors="replace")
        data = json.loads(body) if body else {}
        cids = []
        try:
            cids = data.get("IdentifierList", {}).get("CID", []) or []
        except Exception:
            cids = []
        if not isinstance(cids, list):
            cids = []
        cids = [c for c in cids if isinstance(c, int) and c > 0][:mr]

        results_out = []
        sres_rows_to_add = []
        now_fetch = _now_utc()
        compounds = _load("compounds.json")
        # index by pubchem_cid for upsert
        idx = {}
        for i, c in enumerate(compounds):
            if isinstance(c, dict) and isinstance(c.get("pubchem_cid"), int):
                idx[c["pubchem_cid"]] = i

        # fetch details per CID
        for rank, cid in enumerate(cids, start=1):
            prop_url = f"{base}/compound/cid/{cid}/property/CanonicalSMILES,IsomericSMILES,InChI,InChIKey,MolecularFormula,MolecularWeight,IUPACName/JSON"
            syn_url = f"{base}/compound/cid/{cid}/synonyms/JSON"
            prop_req = urllib.request.Request(prop_url, headers={"User-Agent": "pubchem-mcp-offline/1.0"})
            with urllib.request.urlopen(prop_req, timeout=15) as resp2:
                body2 = resp2.read().decode("utf-8", errors="replace")
            prop = json.loads(body2) if body2 else {}
            props = prop.get("PropertyTable", {}).get("Properties", [])
            p0 = props[0] if isinstance(props, list) and props else {}
            syn_req = urllib.request.Request(syn_url, headers={"User-Agent": "pubchem-mcp-offline/1.0"})
            with urllib.request.urlopen(syn_req, timeout=15) as resp3:
                body3 = resp3.read().decode("utf-8", errors="replace")
            syn = json.loads(body3) if body3 else {}
            syns = syn.get("InformationList", {}).get("Information", [])
            s0 = syns[0] if isinstance(syns, list) and syns else {}
            syn_list = s0.get("Synonym")
            if not isinstance(syn_list, list):
                syn_list = None

            mw = p0.get("MolecularWeight")
            if mw is not None and not isinstance(mw, (int, float)):
                mw = None
            if isinstance(mw, (int, float)) and mw <= 0:
                mw = None

            compound_row = {
                "id": None,  # fill after upsert decision
                "pubchem_cid": cid,
                "canonical_smiles": p0.get("CanonicalSMILES"),
                "isomeric_smiles": p0.get("IsomericSMILES"),
                "inchi": p0.get("InChI"),
                "inchi_key": p0.get("InChIKey"),
                "molecular_formula": p0.get("MolecularFormula"),
                "molecular_weight": mw,
                "iupac_name": p0.get("IUPACName"),
                "synonyms": syn_list,
                "pubchem_json": {"property": prop, "synonyms": syn},
                "cache_status": "fresh",
                "cached_at": _iso(now_fetch),
                "source_url": prop_url,
                "created_at": _iso(now_fetch),
                "updated_at": _iso(now_fetch),
            }

            # upsert by pubchem_cid
            if cid in idx:
                existing = compounds[idx[cid]]
                if not isinstance(existing, dict):
                    existing = {}
                comp_id = existing.get("id") if isinstance(existing.get("id"), str) else _new_id("cmp")
                compound_row["id"] = comp_id
                compound_row["created_at"] = existing.get("created_at") or compound_row["created_at"]
                compounds[idx[cid]] = compound_row
            else:
                comp_id = _new_id("cmp")
                compound_row["id"] = comp_id
                compounds.append(compound_row)
                idx[cid] = len(compounds) - 1

            results_out.append(_normalize_compound(compound_row))
            sres_rows_to_add.append({
                "id": _new_id("res"),
                "search_request_id": req_id,
                "compound_id": compound_row["id"],
                "rank": rank,
                "match_type": "name",
                "score": None,
                "created_at": _iso(now_fetch),
                "updated_at": _iso(now_fetch),
            })

        _save("compounds.json", compounds)

        # persist search_results contiguous ranks
        sres = _load("search_results.json")
        for row in sres_rows_to_add:
            sres.append(row)
        _save("search_results.json", sres)

        # finalize request succeeded
        dur_ms = int((time.time() - start) * 1000)
        finished = _now_utc()
        reqs = _load("search_requests.json")
        for r in reqs:
            if r.get("id") == req_id:
                if r.get("status") != "running":
                    return _err("INVALID_TRANSITION", "search_request must be running before succeeding.")
                r["status"] = "succeeded"
                r["http_status_code"] = http_code
                r["result_count"] = len(results_out)
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(finished)
                break
        _save("search_requests.json", reqs)

        _bump_success_failure(api_key["id"], _now_utc(), succeeded=True)
        _update_key_last_used(api_key["id"], _now_utc())
        return {
            "search_request_id": req_id,
            "served_from_cache": False,
            "result_count": len(results_out),
            "results": results_out,
        }

    except urllib.error.HTTPError as he:
        # mark failed; if name not found in PubChem, return empty results as succeeded? PubChem returns 404 for not found.
        http_code = getattr(he, "code", None)
        dur_ms = int((time.time() - start) * 1000)
        finished = _now_utc()
        # treat 404 as succeeded with 0 results for search endpoints
        if http_code == 404:
            reqs = _load("search_requests.json")
            for r in reqs:
                if r.get("id") == req_id:
                    r["status"] = "succeeded"
                    r["http_status_code"] = http_code
                    r["result_count"] = 0
                    r["duration_ms"] = dur_ms
                    r["served_from_cache"] = False
                    r["updated_at"] = _iso(finished)
                    break
            _save("search_requests.json", reqs)
            _bump_success_failure(api_key["id"], _now_utc(), succeeded=True)
            _update_key_last_used(api_key["id"], _now_utc())
            return {
                "search_request_id": req_id,
                "served_from_cache": False,
                "result_count": 0,
                "results": [],
            }

        reqs = _load("search_requests.json")
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["http_status_code"] = http_code
                r["error_message"] = f"PubChem HTTP error: {http_code}"
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(finished)
                break
        _save("search_requests.json", reqs)
        _bump_success_failure(api_key["id"], _now_utc(), succeeded=False)
        return _err("NOT_FOUND" if http_code == 404 else "CONFLICT", "PubChem request failed.", http_status_code=http_code)
    except urllib.error.URLError as ue:
        dur_ms = int((time.time() - start) * 1000)
        finished = _now_utc()
        reqs = _load("search_requests.json")
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = f"PubChem network error: {getattr(ue, 'reason', str(ue))}"
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(finished)
                break
        _save("search_requests.json", reqs)
        _bump_success_failure(api_key["id"], _now_utc(), succeeded=False)
        return _err("CONFLICT", "PubChem network error.")
    except json.JSONDecodeError:
        dur_ms = int((time.time() - start) * 1000)
        finished = _now_utc()
        reqs = _load("search_requests.json")
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "PubChem returned invalid JSON."
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(finished)
                break
        _save("search_requests.json", reqs)
        _bump_success_failure(api_key["id"], _now_utc(), succeeded=False)
        return _err("CONFLICT", "PubChem returned invalid JSON.")
    except Exception:
        # unexpected - must not raise
        dur_ms = int((time.time() - start) * 1000)
        finished = _now_utc()
        reqs = _load("search_requests.json")
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "Internal error."
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(finished)
                break
        _save("search_requests.json", reqs)
        _bump_success_failure(api_key["id"], _now_utc(), succeeded=False)
        return _err("CONFLICT", "Internal error.")

def search_pubchem_by_smiles(smiles, max_results=None, **_extra):
    import json, os, datetime, time, hashlib, urllib.parse, urllib.request, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0145000" if __import__("os").path.isdir("./environment_mix/0145000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        try:
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + ':' + str(time.time_ns())).encode('utf-8')).hexdigest()[:24]}"

    def _norm_str(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        return s.strip()

    def _clamp_max_results(v):
        if v is None:
            v = 5
        if not isinstance(v, int):
            return None, _err("VALIDATION_ERROR", "max_results must be an integer between 1 and 100.")
        if v < 1 or v > 100:
            return None, _err("VALIDATION_ERROR", "max_results must be between 1 and 100.")
        return v, None

    def _valid_smiles(s):
        # lightweight validation: non-empty, reasonable chars, balanced brackets/parens
        if not isinstance(s, str):
            return False
        if s == "" or len(s) > 2000:
            return False
        if not re.fullmatch(r"[A-Za-z0-9@\+\-\=\#\%\.\(\)\[\]\\\/:]*", s):
            return False
        stack = []
        pairs = {")": "(", "]": "["}
        for ch in s:
            if ch in "([":
                stack.append(ch)
            elif ch in ")]":
                if not stack or stack[-1] != pairs[ch]:
                    return False
                stack.pop()
        return not stack

    def _resolve_active_key():
        keys = _load("api_keys.json")
        active = [k for k in keys if isinstance(k, dict) and k.get("status") == "active"]
        if not active:
            return None
        active.sort(key=lambda k: (k.get("daily_request_limit") if isinstance(k.get("daily_request_limit"), int) else -1,
                                  k.get("per_minute_limit") if isinstance(k.get("per_minute_limit"), int) else -1),
                    reverse=True)
        return active[0]

    def _window_starts(now):
        day_start = now.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)
        minute_start = now.astimezone(datetime.timezone.utc).replace(second=0, microsecond=0)
        return day_start, minute_start

    def _get_or_create_counter(counters, api_key_id, window_type, window_start, now):
        ws = _iso(window_start)
        for c in counters:
            if c.get("api_key_id") == api_key_id and c.get("window_type") == window_type and c.get("window_start") == ws:
                return c
        row = {
            "id": _new_id("uc"),
            "api_key_id": api_key_id,
            "window_type": window_type,
            "window_start": ws,
            "request_count": 0,
            "succeeded_count": 0,
            "failed_count": 0,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        counters.append(row)
        return row

    def _enforce_limits(api_key_row, now):
        if api_key_row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active.")
        daily_limit = api_key_row.get("daily_request_limit")
        per_min_limit = api_key_row.get("per_minute_limit")
        if not isinstance(daily_limit, int) or daily_limit < 0:
            return _err("VALIDATION_ERROR", "API key has invalid daily_request_limit.")
        if not isinstance(per_min_limit, int) or per_min_limit < 0:
            return _err("VALIDATION_ERROR", "API key has invalid per_minute_limit.")

        counters = _load("usage_counters.json")
        day_start, minute_start = _window_starts(now)
        day_c = _get_or_create_counter(counters, api_key_row["id"], "day", day_start, now)
        min_c = _get_or_create_counter(counters, api_key_row["id"], "minute", minute_start, now)

        if per_min_limit == 0:
            _save("usage_counters.json", counters)
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded.")
        if daily_limit == 0:
            _save("usage_counters.json", counters)
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")
        if int(min_c.get("request_count") or 0) >= per_min_limit:
            _save("usage_counters.json", counters)
            return _err("RATE_LIMIT", "Per-minute rate limit exceeded.")
        if int(day_c.get("request_count") or 0) >= daily_limit:
            _save("usage_counters.json", counters)
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

        for c in (day_c, min_c):
            c["request_count"] = int(c.get("request_count") or 0) + 1
            c["updated_at"] = _iso(now)
        _save("usage_counters.json", counters)
        return None

    def _bump_success_failure(api_key_id, now, succeeded):
        counters = _load("usage_counters.json")
        day_start, minute_start = _window_starts(now)
        day_ws = _iso(day_start)
        min_ws = _iso(minute_start)
        for c in counters:
            if c.get("api_key_id") != api_key_id:
                continue
            if c.get("window_type") == "day" and c.get("window_start") == day_ws:
                if succeeded:
                    c["succeeded_count"] = int(c.get("succeeded_count") or 0) + 1
                else:
                    c["failed_count"] = int(c.get("failed_count") or 0) + 1
                c["updated_at"] = _iso(now)
            if c.get("window_type") == "minute" and c.get("window_start") == min_ws:
                if succeeded:
                    c["succeeded_count"] = int(c.get("succeeded_count") or 0) + 1
                else:
                    c["failed_count"] = int(c.get("failed_count") or 0) + 1
                c["updated_at"] = _iso(now)
        _save("usage_counters.json", counters)

    def _fingerprint(tool, params):
        b = json.dumps({"tool": tool, **params}, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(b.encode("utf-8")).hexdigest()

    def _same_utc_date(dt, now):
        ddt = _parse_dt(dt)
        if not ddt:
            return False
        return ddt.astimezone(datetime.timezone.utc).date() == now.astimezone(datetime.timezone.utc).date()

    def _find_cached_request(api_key_id, tool_name, fingerprint, now):
        reqs = _load("search_requests.json")
        candidates = []
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            if r.get("tool_name") != tool_name:
                continue
            if r.get("request_fingerprint") != fingerprint:
                continue
            if not _same_utc_date(r.get("created_at"), now):
                continue
            if r.get("status") == "succeeded":
                candidates.append(r)
        candidates.sort(key=lambda r: _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), reverse=True)
        return candidates[0] if candidates else None

    def _get_results_for_request(req_id):
        results = _load("search_results.json")
        compounds = _load("compounds.json")
        comp_by_id = {c.get("id"): c for c in compounds if isinstance(c, dict) and isinstance(c.get("id"), str)}
        rows = []
        for sr in results:
            if not isinstance(sr, dict):
                continue
            if sr.get("search_request_id") != req_id:
                continue
            c = comp_by_id.get(sr.get("compound_id"))
            if c:
                rows.append((sr, c))
        rows.sort(key=lambda t: int(t[0].get("rank") or 0))
        return rows

    def _normalize_compound(c):
        return {
            "cid": c.get("pubchem_cid"),
            "canonical_smiles": c.get("canonical_smiles"),
            "isomeric_smiles": c.get("isomeric_smiles"),
            "inchi": c.get("inchi"),
            "inchi_key": c.get("inchi_key"),
            "molecular_formula": c.get("molecular_formula"),
            "molecular_weight": c.get("molecular_weight"),
            "iupac_name": c.get("iupac_name"),
            "synonyms": c.get("synonyms") if isinstance(c.get("synonyms"), list) else None,
            "source_url": c.get("source_url"),
            "cached_at": c.get("cached_at"),
            "cache_status": c.get("cache_status"),
        }

    def _update_key_last_used(api_key_id, now):
        keys = _load("api_keys.json")
        for k in keys:
            if isinstance(k, dict) and k.get("id") == api_key_id:
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                _save("api_keys.json", keys)
                return

    start = time.time()
    now = _now_utc()

    smi = _norm_str(smiles)
    if smi is None:
        return _err("VALIDATION_ERROR", "smiles must be a string.")
    if smi == "":
        return _err("VALIDATION_ERROR", "smiles must be non-empty.")
    if not _valid_smiles(smi):
        return _err("VALIDATION_ERROR", "smiles is not a valid SMILES string.")

    mr, e = _clamp_max_results(max_results)
    if e:
        return e

    api_key = _resolve_active_key()
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    tool_name = "search_pubchem_by_smiles"
    fp = _fingerprint(tool_name, {"smiles": smi, "max_results": mr})

    limit_err = _enforce_limits(api_key, now)
    if limit_err:
        reqs = _load("search_requests.json")
        req_id = _new_id("sr")
        dur_ms = int((time.time() - start) * 1000)
        reqs.append({
            "id": req_id,
            "api_key_id": api_key["id"],
            "tool_name": tool_name,
            "name": None,
            "smiles": smi,
            "formula": None,
            "cid": None,
            "max_results": mr,
            "status": "failed",
            "http_status_code": None,
            "error_message": limit_err["error"]["message"],
            "request_fingerprint": fp,
            "served_from_cache": True,
            "result_count": 0,
            "duration_ms": dur_ms,
            "created_at": _iso(now),
            "updated_at": _iso(_now_utc()),
        })
        _save("search_requests.json", reqs)
        _bump_success_failure(api_key["id"], _now_utc(), succeeded=False)
        return limit_err

    cached = _find_cached_request(api_key["id"], tool_name, fp, now)
    if cached:
        rows = _get_results_for_request(cached["id"])
        out = []
        for sr, comp in rows[:mr]:
            out.append(_normalize_compound(comp))
        dur_ms = int((time.time() - start) * 1000)

        reqs = _load("search_requests.json")
        req_id = _new_id("sr")
        created = _now_utc()
        reqs.append({
            "id": req_id,
            "api_key_id": api_key["id"],
            "tool_name": tool_name,
            "name": None,
            "smiles": smi,
            "formula": None,
            "cid": None,
            "max_results": mr,
            "status": "queued",
            "http_status_code": None,
            "error_message": None,
            "request_fingerprint": fp,
            "served_from_cache": True,
            "result_count": len(out),
            "duration_ms": None,
            "created_at": _iso(created),
            "updated_at": _iso(created),
        })
        _save("search_requests.json", reqs)

        reqs = _load("search_requests.json")
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "running"
                r["updated_at"] = _iso(_now_utc())
                break
        _save("search_requests.json", reqs)

        reqs = _load("search_requests.json")
        finished = _now_utc()
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "succeeded"
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(finished)
                r["result_count"] = len(out)
                break
        _save("search_requests.json", reqs)

        sres = _load("search_results.json")
        now2 = _now_utc()
        cached_pairs = _get_results_for_request(cached["id"])[:len(out)]
        rank = 1
        for _sr, comp in cached_pairs:
            sres.append({
                "id": _new_id("res"),
                "search_request_id": req_id,
                "compound_id": comp.get("id"),
                "rank": rank,
                "match_type": "smiles",
                "score": None,
                "created_at": _iso(now2),
                "updated_at": _iso(now2),
            })
            rank += 1
        _save("search_results.json", sres)

        _bump_success_failure(api_key["id"], _now_utc(), succeeded=True)
        _update_key_last_used(api_key["id"], _now_utc())
        return {
            "search_request_id": req_id,
            "served_from_cache": True,
            "result_count": len(out),
            "results": out,
        }

    reqs = _load("search_requests.json")
    req_id = _new_id("sr")
    created = _now_utc()
    reqs.append({
        "id": req_id,
        "api_key_id": api_key["id"],
        "tool_name": tool_name,
        "name": None,
        "smiles": smi,
        "formula": None,
        "cid": None,
        "max_results": mr,
        "status": "queued",
        "http_status_code": None,
        "error_message": None,
        "request_fingerprint": fp,
        "served_from_cache": False,
        "result_count": 0,
        "duration_ms": None,
        "created_at": _iso(created),
        "updated_at": _iso(created),
    })
    _save("search_requests.json", reqs)

    reqs = _load("search_requests.json")
    for r in reqs:
        if r.get("id") == req_id:
            r["status"] = "running"
            r["updated_at"] = _iso(_now_utc())
            break
    _save("search_requests.json", reqs)

    try:
        base = "https://pubchem.ncbi.nlm.nih.gov/rest/pug"
        # use canonical SMILES search to get CIDs
        url_cids = f"{base}/compound/smiles/{urllib.parse.quote(smi)}/cids/JSON"
        req = urllib.request.Request(url_cids, headers={"User-Agent": "pubchem-mcp-offline/1.0"})
        with urllib.request.urlopen(req, timeout=20) as resp:
            http_code = getattr(resp, "status", None)
            body = resp.read().decode("utf-8", errors="replace")
        data = json.loads(body) if body else {}
        cids = data.get("IdentifierList", {}).get("CID", []) or []
        if not isinstance(cids, list):
            cids = []
        cids = [c for c in cids if isinstance(c, int) and c > 0][:mr]

        results_out = []
        sres_rows_to_add = []
        now_fetch = _now_utc()
        compounds = _load("compounds.json")
        idx = {}
        for i, c in enumerate(compounds):
            if isinstance(c, dict) and isinstance(c.get("pubchem_cid"), int):
                idx[c["pubchem_cid"]] = i

        for rank, cid in enumerate(cids, start=1):
            prop_url = f"{base}/compound/cid/{cid}/property/CanonicalSMILES,IsomericSMILES,InChI,InChIKey,MolecularFormula,MolecularWeight,IUPACName/JSON"
            syn_url = f"{base}/compound/cid/{cid}/synonyms/JSON"
            prop_req = urllib.request.Request(prop_url, headers={"User-Agent": "pubchem-mcp-offline/1.0"})
            with urllib.request.urlopen(prop_req, timeout=15) as resp2:
                body2 = resp2.read().decode("utf-8", errors="replace")
            prop = json.loads(body2) if body2 else {}
            props = prop.get("PropertyTable", {}).get("Properties", [])
            p0 = props[0] if isinstance(props, list) and props else {}
            syn_req = urllib.request.Request(syn_url, headers={"User-Agent": "pubchem-mcp-offline/1.0"})
            with urllib.request.urlopen(syn_req, timeout=15) as resp3:
                body3 = resp3.read().decode("utf-8", errors="replace")
            syn = json.loads(body3) if body3 else {}
            syns = syn.get("InformationList", {}).get("Information", [])
            s0 = syns[0] if isinstance(syns, list) and syns else {}
            syn_list = s0.get("Synonym")
            if not isinstance(syn_list, list):
                syn_list = None

            mw = p0.get("MolecularWeight")
            if mw is not None and not isinstance(mw, (int, float)):
                mw = None
            if isinstance(mw, (int, float)) and mw <= 0:
                mw = None

            compound_row = {
                "id": None,
                "pubchem_cid": cid,
                "canonical_smiles": p0.get("CanonicalSMILES"),
                "isomeric_smiles": p0.get("IsomericSMILES"),
                "inchi": p0.get("InChI"),
                "inchi_key": p0.get("InChIKey"),
                "molecular_formula": p0.get("MolecularFormula"),
                "molecular_weight": mw,
                "iupac_name": p0.get("IUPACName"),
                "synonyms": syn_list,
                "pubchem_json": {"property": prop, "synonyms": syn},
                "cache_status": "fresh",
                "cached_at": _iso(now_fetch),
                "source_url": prop_url,
                "created_at": _iso(now_fetch),
                "updated_at": _iso(now_fetch),
            }

            if cid in idx:
                existing = compounds[idx[cid]]
                comp_id = existing.get("id") if isinstance(existing, dict) and isinstance(existing.get("id"), str) else _new_id("cmp")
                compound_row["id"] = comp_id
                compound_row["created_at"] = existing.get("created_at") if isinstance(existing, dict) else compound_row["created_at"]
                compounds[idx[cid]] = compound_row
            else:
                comp_id = _new_id("cmp")
                compound_row["id"] = comp_id
                compounds.append(compound_row)
                idx[cid] = len(compounds) - 1

            results_out.append(_normalize_compound(compound_row))
            sres_rows_to_add.append({
                "id": _new_id("res"),
                "search_request_id": req_id,
                "compound_id": compound_row["id"],
                "rank": rank,
                "match_type": "smiles",
                "score": None,
                "created_at": _iso(now_fetch),
                "updated_at": _iso(now_fetch),
            })

        _save("compounds.json", compounds)
        sres = _load("search_results.json")
        sres.extend(sres_rows_to_add)
        _save("search_results.json", sres)

        dur_ms = int((time.time() - start) * 1000)
        finished = _now_utc()
        reqs = _load("search_requests.json")
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "succeeded"
                r["http_status_code"] = http_code
                r["result_count"] = len(results_out)
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(finished)
                break
        _save("search_requests.json", reqs)

        _bump_success_failure(api_key["id"], _now_utc(), succeeded=True)
        _update_key_last_used(api_key["id"], _now_utc())
        return {
            "search_request_id": req_id,
            "served_from_cache": False,
            "result_count": len(results_out),
            "results": results_out,
        }

    except urllib.error.HTTPError as he:
        http_code = getattr(he, "code", None)
        dur_ms = int((time.time() - start) * 1000)
        finished = _now_utc()
        if http_code == 404:
            reqs = _load("search_requests.json")
            for r in reqs:
                if r.get("id") == req_id:
                    r["status"] = "succeeded"
                    r["http_status_code"] = http_code
                    r["result_count"] = 0
                    r["duration_ms"] = dur_ms
                    r["updated_at"] = _iso(finished)
                    break
            _save("search_requests.json", reqs)
            _bump_success_failure(api_key["id"], _now_utc(), succeeded=True)
            _update_key_last_used(api_key["id"], _now_utc())
            return {"search_request_id": req_id, "served_from_cache": False, "result_count": 0, "results": []}

        reqs = _load("search_requests.json")
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["http_status_code"] = http_code
                r["error_message"] = f"PubChem HTTP error: {http_code}"
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(finished)
                break
        _save("search_requests.json", reqs)
        _bump_success_failure(api_key["id"], _now_utc(), succeeded=False)
        return _err("CONFLICT", "PubChem request failed.", http_status_code=http_code)
    except urllib.error.URLError as ue:
        dur_ms = int((time.time() - start) * 1000)
        finished = _now_utc()
        reqs = _load("search_requests.json")
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = f"PubChem network error: {getattr(ue, 'reason', str(ue))}"
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(finished)
                break
        _save("search_requests.json", reqs)
        _bump_success_failure(api_key["id"], _now_utc(), succeeded=False)
        return _err("CONFLICT", "PubChem network error.")
    except json.JSONDecodeError:
        dur_ms = int((time.time() - start) * 1000)
        finished = _now_utc()
        reqs = _load("search_requests.json")
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "PubChem returned invalid JSON."
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(finished)
                break
        _save("search_requests.json", reqs)
        _bump_success_failure(api_key["id"], _now_utc(), succeeded=False)
        return _err("CONFLICT", "PubChem returned invalid JSON.")
    except Exception:
        dur_ms = int((time.time() - start) * 1000)
        finished = _now_utc()
        reqs = _load("search_requests.json")
        for r in reqs:
            if r.get("id") == req_id:
                r["status"] = "failed"
                r["error_message"] = "Internal error."
                r["duration_ms"] = dur_ms
                r["updated_at"] = _iso(finished)
                break
        _save("search_requests.json", reqs)
        _bump_success_failure(api_key["id"], _now_utc(), succeeded=False)
        return _err("CONFLICT", "Internal error.")

def search_pubchem_advanced(name=None, smiles=None, formula=None, cid=None, max_results=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0145000" if __import__("os").path.isdir("./environment_mix/0145000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _truncate_day(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, 0, 0, 0, tzinfo=datetime.timezone.utc)

    def _truncate_minute(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(second=0, microsecond=0)

    def _gen_id(prefix):
        seed = f"{prefix}:{_iso(_now())}:{os.urandom(16).hex()}"
        return f"{prefix}_{hashlib.sha256(seed.encode('utf-8')).hexdigest()[:26]}"

    def _norm_str_or_none(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return "__BADTYPE__"
        return v.strip()

    # ---- Validate inputs (RELAXED to accept all-null like vendor tool schema default) ----
    n = _norm_str_or_none(name)
    s = _norm_str_or_none(smiles)
    f = _norm_str_or_none(formula)

    if n == "__BADTYPE__":
        return _err("VALIDATION_ERROR", "name must be a string or null")
    if s == "__BADTYPE__":
        return _err("VALIDATION_ERROR", "smiles must be a string or null")
    if f == "__BADTYPE__":
        return _err("VALIDATION_ERROR", "formula must be a string or null")
    if cid is not None and not isinstance(cid, int):
        return _err("VALIDATION_ERROR", "cid must be an integer or null")

    # Treat blank strings as nulls for advanced search.
    if isinstance(n, str) and n == "":
        n = None
    if isinstance(s, str) and s == "":
        s = None
    if isinstance(f, str) and f == "":
        f = None

    if cid is not None and cid <= 0:
        return _err("VALIDATION_ERROR", "cid must be > 0")

    if max_results is None:
        max_results = 5
    if not isinstance(max_results, int):
        return _err("VALIDATION_ERROR", "max_results must be an integer")
    if max_results < 1 or max_results > 100:
        return _err("VALIDATION_ERROR", "max_results must be between 1 and 100")

    # ---- Resolve an active API key context that can serve the call ----
    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")
    compounds = _load("compounds.json")
    usage = _load("usage_counters.json")

    active_keys = [k for k in api_keys if k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key context available")

    now = _now()
    minute_start = _truncate_minute(now)
    day_start = _truncate_day(now)
    minute_start_iso = _iso(minute_start)
    day_start_iso = _iso(day_start)

    def _counter_for(api_key_id, window_type, window_start_iso):
        for row in usage:
            if row.get("api_key_id") == api_key_id and row.get("window_type") == window_type and row.get("window_start") == window_start_iso:
                return row
        return None

    def _count_for(api_key, window_type, window_start_iso):
        row = _counter_for(api_key.get("id"), window_type, window_start_iso)
        if not row:
            return 0
        try:
            return int(row.get("request_count", 0))
        except Exception:
            return 0

    # Choose a key that is under both limits (search for a combination that exists).
    chosen_key = None
    for k in active_keys:
        try:
            per_minute = int(k.get("per_minute_limit", 0))
            per_day = int(k.get("daily_request_limit", 0))
        except Exception:
            continue
        if per_minute < 0 or per_day < 0:
            continue
        if _count_for(k, "minute", minute_start_iso) >= per_minute:
            continue
        if _count_for(k, "day", day_start_iso) >= per_day:
            continue
        chosen_key = k
        break

    if not chosen_key:
        # Rate limit blocks the request; still log a failed request row (attempt may be logged as failed).
        chosen_key = active_keys[0]  # associate with some active key for logging
        # Increment counters as "failed" attempt (gateway observed dynamics)
        def _touch_counter(api_key_id, window_type, window_start_iso, succeeded):
            row = _counter_for(api_key_id, window_type, window_start_iso)
            ts = _iso(now)
            if not row:
                row = {
                    "id": _gen_id("pcuc"),
                    "api_key_id": api_key_id,
                    "window_type": window_type,
                    "window_start": window_start_iso,
                    "request_count": 0,
                    "succeeded_count": 0,
                    "failed_count": 0,
                    "created_at": ts,
                    "updated_at": ts
                }
                usage.append(row)
            row["request_count"] = int(row.get("request_count", 0)) + 1
            if succeeded:
                row["succeeded_count"] = int(row.get("succeeded_count", 0)) + 1
            else:
                row["failed_count"] = int(row.get("failed_count", 0)) + 1
            row["updated_at"] = ts
            # enforce invariant
            row["request_count"] = int(row["succeeded_count"]) + int(row["failed_count"])

        # Create request row (queued->running->failed)
        created_at = _iso(now)
        params_norm = {"name": n, "smiles": s, "formula": f, "cid": cid, "max_results": max_results}
        fp_src = json.dumps(params_norm, sort_keys=True, ensure_ascii=False)
        fingerprint = hashlib.sha256(fp_src.encode("utf-8")).hexdigest()

        req_id = _gen_id("pcrq")
        req = {
            "id": req_id,
            "api_key_id": chosen_key.get("id"),
            "tool_name": "search_pubchem_advanced",
            "name": n,
            "smiles": s,
            "formula": f,
            "cid": cid,
            "max_results": max_results,
            "status": "queued",
            "http_status_code": None,
            "error_message": None,
            "request_fingerprint": fingerprint,
            "served_from_cache": False,
            "result_count": 0,
            "duration_ms": None,
            "created_at": created_at,
            "updated_at": created_at
        }
        search_requests.append(req)
        # transitions
        req["status"] = "running"
        req["updated_at"] = _iso(_now())
        req["status"] = "failed"
        req["error_message"] = "Rate limit exceeded at gateway: quota reached"
        req["updated_at"] = _iso(_now())
        req["duration_ms"] = max(0, int((time.time() - t0) * 1000))

        _touch_counter(chosen_key.get("id"), "minute", minute_start_iso, succeeded=False)
        _touch_counter(chosen_key.get("id"), "day", day_start_iso, succeeded=False)

        _save("usage_counters.json", usage)
        _save("search_requests.json", search_requests)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # ---- Helpers: record usage (every call) ----
    def _touch_counter(api_key_id, window_type, window_start_iso, succeeded):
        row = _counter_for(api_key_id, window_type, window_start_iso)
        ts = _iso(now)
        if not row:
            row = {
                "id": _gen_id("pcuc"),
                "api_key_id": api_key_id,
                "window_type": window_type,
                "window_start": window_start_iso,
                "request_count": 0,
                "succeeded_count": 0,
                "failed_count": 0,
                "created_at": ts,
                "updated_at": ts
            }
            usage.append(row)
        row["request_count"] = int(row.get("request_count", 0)) + 1
        if succeeded:
            row["succeeded_count"] = int(row.get("succeeded_count", 0)) + 1
        else:
            row["failed_count"] = int(row.get("failed_count", 0)) + 1
        row["updated_at"] = ts
        row["request_count"] = int(row["succeeded_count"]) + int(row["failed_count"])

    # Enforce limits for chosen key (we already selected one under limits, but re-check)
    if _count_for(chosen_key, "minute", minute_start_iso) >= int(chosen_key.get("per_minute_limit", 0)):
        return _err("RATE_LIMIT", "Rate limit exceeded")
    if _count_for(chosen_key, "day", day_start_iso) >= int(chosen_key.get("daily_request_limit", 0)):
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded")

    # ---- Create search_requests row (always) ----
    created_at = _iso(now)
    params_norm = {"name": n, "smiles": s, "formula": f, "cid": cid, "max_results": max_results}
    fp_src = json.dumps(params_norm, sort_keys=True, ensure_ascii=False)
    fingerprint = hashlib.sha256(fp_src.encode("utf-8")).hexdigest()

    req_id = _gen_id("pcrq")
    req = {
        "id": req_id,
        "api_key_id": chosen_key.get("id"),
        "tool_name": "search_pubchem_advanced",
        "name": n,
        "smiles": s,
        "formula": f,
        "cid": cid,
        "max_results": max_results,
        "status": "queued",
        "http_status_code": None,
        "error_message": None,
        "request_fingerprint": fingerprint,
        "served_from_cache": False,
        "result_count": 0,
        "duration_ms": None,
        "created_at": created_at,
        "updated_at": created_at
    }
    search_requests.append(req)

    # queued -> running transition required
    req["status"] = "running"
    req["updated_at"] = _iso(_now())

    # ---- Serve from local datastore/cache only (offline), and be permissive for all-null queries ----
    # If no search fields provided: return empty result set successfully (relaxed per audit).
    results_compounds = []
    match_type = None

    try:
        if cid is not None:
            match_type = "cid"
            for c in compounds:
                if isinstance(c, dict) and c.get("pubchem_cid") == cid:
                    results_compounds = [c]
                    break
        else:
            # Filter compounds by any provided fields (AND semantics for provided fields)
            def _has_name(c):
                q = (n or "").lower()
                if not q:
                    return True
                if isinstance(c.get("iupac_name"), str) and q in c["iupac_name"].lower():
                    return True
                syns = c.get("synonyms")
                if isinstance(syns, list):
                    for syn in syns:
                        if isinstance(syn, str) and q in syn.lower():
                            return True
                return False

            def _has_smiles(c):
                q = s
                if not q:
                    return True
                # simple contains match against stored smiles
                for k in ("canonical_smiles", "isomeric_smiles"):
                    v = c.get(k)
                    if isinstance(v, str) and v.strip() == q:
                        return True
                return False

            def _has_formula(c):
                q = f
                if not q:
                    return True
                v = c.get("molecular_formula")
                return isinstance(v, str) and v.strip() == q

            if n is not None:
                match_type = "name"
            if s is not None:
                match_type = "smiles" if match_type is None else "mixed"
            if f is not None:
                match_type = "formula" if match_type is None else "mixed"
            if match_type is None:
                match_type = "mixed"

            filtered = []
            for c in compounds:
                if not isinstance(c, dict):
                    continue
                if not _has_name(c):
                    continue
                if not _has_smiles(c):
                    continue
                if not _has_formula(c):
                    continue
                filtered.append(c)

            # deterministic ordering: by pubchem_cid asc when present else id
            filtered.sort(key=lambda x: (x.get("pubchem_cid") if isinstance(x.get("pubchem_cid"), int) else 10**18, x.get("id", "")))
            results_compounds = filtered[:max_results]
    except Exception:
        # Do not raise; mark request failed
        req["status"] = "failed"
        req["error_message"] = "Internal error while searching local cache"
        req["updated_at"] = _iso(_now())
        req["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        _touch_counter(chosen_key.get("id"), "minute", minute_start_iso, succeeded=False)
        _touch_counter(chosen_key.get("id"), "day", day_start_iso, succeeded=False)
        _save("usage_counters.json", usage)
        _save("search_requests.json", search_requests)
        return _err("FAILED", "Internal error")

    # ---- Persist search_results rows contiguously with rank starting 1 ----
    # Remove any existing results for this request id (should not exist, but idempotent)
    search_results = [r for r in search_results if r.get("search_request_id") != req_id]

    ts_now = _iso(_now())
    out_rows = []
    rank = 1
    for c in results_compounds[:max_results]:
        compound_id = c.get("id")
        if not isinstance(compound_id, str) or not compound_id:
            continue
        row = {
            "id": _gen_id("pcrs"),
            "search_request_id": req_id,
            "compound_id": compound_id,
            "rank": rank,
            "match_type": match_type if match_type in ("name", "smiles", "formula", "cid", "mixed") else "mixed",
            "score": None,
            "created_at": ts_now,
            "updated_at": ts_now
        }
        out_rows.append(row)
        rank += 1

    search_results.extend(out_rows)

    # ---- Complete request: running -> succeeded ----
    req["served_from_cache"] = True
    req["http_status_code"] = None
    req["result_count"] = len(out_rows)
    req["status"] = "succeeded"
    req["updated_at"] = ts_now
    req["duration_ms"] = max(0, int((time.time() - t0) * 1000))

    # Update api_key last_used_at on success
    chosen_key["last_used_at"] = ts_now
    chosen_key["updated_at"] = ts_now

    _touch_counter(chosen_key.get("id"), "minute", minute_start_iso, succeeded=True)
    _touch_counter(chosen_key.get("id"), "day", day_start_iso, succeeded=True)

    _save("search_results.json", search_results)
    _save("search_requests.json", search_requests)
    _save("usage_counters.json", usage)
    _save("api_keys.json", api_keys)

    # Return normalized compound summaries (no pagination)
    def _summary(c):
        return {
            "cid": c.get("pubchem_cid"),
            "molecular_formula": c.get("molecular_formula"),
            "molecular_weight": c.get("molecular_weight"),
            "iupac_name": c.get("iupac_name"),
            "canonical_smiles": c.get("canonical_smiles"),
            "inchi": c.get("inchi"),
            "inchi_key": c.get("inchi_key"),
            "cache_status": c.get("cache_status"),
            "cached_at": c.get("cached_at"),
            "compound_id": c.get("id")
        }

    return {
        "search_request": req,
        "results": [_summary(c) for c in results_compounds[:len(out_rows)]],
        "meta": {"max_results": max_results, "result_count": len(out_rows)}
    }

def list_search_requests(status=None, tool_name=None, served_from_cache=None, created_after=None, created_before=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0145000" if __import__("os").path.isdir("./environment_mix/0145000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _now_utc().isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string"))
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return ("__err__", _err("VALIDATION_ERROR", f"{field} must be an RFC3339 datetime string"))

    def _truncate_day(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, 0, 0, 0, tzinfo=datetime.timezone.utc)

    def _truncate_minute(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(second=0, microsecond=0)

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256(f'{prefix}:{_iso(_now_utc())}:{os.urandom(8).hex()}'.encode('utf-8')).hexdigest()[:24]}"

    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    usage = _load("usage_counters.json")

    # Authenticate ambient: pick any active key (caller is authenticated by environment in this simulation)
    api_key = None
    for k in api_keys:
        if k.get("status") == "active":
            api_key = k
            break
    if not api_key:
        # If there are keys but none active, still treat as unauthorized for execution/reads requiring key context
        return _err("UNAUTHORIZED", "No active API key context available")

    # Validate inputs
    valid_status = {"queued", "running", "succeeded", "failed"}
    valid_tool = {"search_pubchem_by_name", "search_pubchem_by_smiles", "get_pubchem_compound_by_cid", "search_pubchem_advanced"}

    if status is not None:
        if not isinstance(status, str) or status not in valid_status:
            return _err("VALIDATION_ERROR", "status must be one of queued, running, succeeded, failed")
    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in valid_tool:
            return _err("VALIDATION_ERROR", "tool_name must be one of the supported tool names")
    if served_from_cache is not None and not isinstance(served_from_cache, bool):
        return _err("VALIDATION_ERROR", "served_from_cache must be a boolean")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100")

    ca = _parse_dt(created_after, "created_after")
    if isinstance(ca, tuple) and ca[0] == "__err__":
        return ca[1]
    cb = _parse_dt(created_before, "created_before")
    if isinstance(cb, tuple) and cb[0] == "__err__":
        return cb[1]
    if isinstance(ca, datetime.datetime) and isinstance(cb, datetime.datetime) and ca > cb:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before")

    # Rate limiting (counts all calls, reads included)
    now = _now_utc()
    minute_start = _truncate_minute(now)
    day_start = _truncate_day(now)

    def _find_counter(window_type, window_start):
        for row in usage:
            if row.get("api_key_id") == api_key.get("id") and row.get("window_type") == window_type and row.get("window_start") == _iso(window_start):
                return row
        return None

    minute_row = _find_counter("minute", minute_start)
    day_row = _find_counter("day", day_start)

    minute_count = int(minute_row.get("request_count")) if minute_row else 0
    day_count = int(day_row.get("request_count")) if day_row else 0

    per_minute_limit = int(api_key.get("per_minute_limit", 0))
    daily_limit = int(api_key.get("daily_request_limit", 0))

    if per_minute_limit >= 0 and minute_count >= per_minute_limit:
        return _err("RATE_LIMIT", "Per-minute rate limit exceeded", limit=per_minute_limit, window_type="minute")
    if daily_limit >= 0 and day_count >= daily_limit:
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", limit=daily_limit, window_type="day")

    # Increment counters as this call is being processed (assume will be succeeded unless we hit an error later)
    def _bump_counters(succeeded):
        nonlocal minute_row, day_row
        ts = _iso(now)
        if minute_row is None:
            minute_row = {
                "id": _gen_id("uc"),
                "api_key_id": api_key["id"],
                "window_type": "minute",
                "window_start": _iso(minute_start),
                "request_count": 0,
                "succeeded_count": 0,
                "failed_count": 0,
                "created_at": ts,
                "updated_at": ts,
            }
            usage.append(minute_row)
        if day_row is None:
            day_row = {
                "id": _gen_id("uc"),
                "api_key_id": api_key["id"],
                "window_type": "day",
                "window_start": _iso(day_start),
                "request_count": 0,
                "succeeded_count": 0,
                "failed_count": 0,
                "created_at": ts,
                "updated_at": ts,
            }
            usage.append(day_row)

        minute_row["request_count"] = int(minute_row["request_count"]) + 1
        day_row["request_count"] = int(day_row["request_count"]) + 1
        if succeeded:
            minute_row["succeeded_count"] = int(minute_row["succeeded_count"]) + 1
            day_row["succeeded_count"] = int(day_row["succeeded_count"]) + 1
        else:
            minute_row["failed_count"] = int(minute_row["failed_count"]) + 1
            day_row["failed_count"] = int(day_row["failed_count"]) + 1
        minute_row["updated_at"] = ts
        day_row["updated_at"] = ts

        # enforce invariant request_count = succeeded + failed
        minute_row["request_count"] = int(minute_row["succeeded_count"]) + int(minute_row["failed_count"])
        day_row["request_count"] = int(day_row["succeeded_count"]) + int(day_row["failed_count"])

    # Apply filters (owned by caller)
    rows = [r for r in search_requests if r.get("api_key_id") == api_key.get("id")]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if served_from_cache is not None:
        rows = [r for r in rows if bool(r.get("served_from_cache")) == served_from_cache]

    if isinstance(ca, datetime.datetime):
        def _created_dt(r):
            s = r.get("created_at")
            if not isinstance(s, str):
                return None
            try:
                ss = s.strip()
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None
        rows = [r for r in rows if (_created_dt(r) is not None and _created_dt(r) >= ca)]
    if isinstance(cb, datetime.datetime):
        def _created_dt2(r):
            s = r.get("created_at")
            if not isinstance(s, str):
                return None
            try:
                ss = s.strip()
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(ss)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            except ValueError:
                return None
        rows = [r for r in rows if (_created_dt2(r) is not None and _created_dt2(r) <= cb)]

    # Sort most recent first by created_at then id
    def _sort_key(r):
        s = r.get("created_at") or ""
        return (s, r.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_items = rows[start:end]
    has_more = end < total

    # Mark key last_used_at on successful call
    api_key["last_used_at"] = _iso(now)
    api_key["updated_at"] = _iso(now)

    # Persist counters as succeeded
    _bump_counters(succeeded=True)
    _save("usage_counters.json", usage)
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": page_items,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
            "api_key_id": api_key.get("id"),
            "latency_ms": latency_ms,
        }
    }

def list_search_results(search_request_id, page=None, page_size=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0145000" if __import__("os").path.isdir("./environment_mix/0145000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _now_utc().isoformat().replace("+00:00", "Z")

    def _truncate_day(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, 0, 0, 0, tzinfo=datetime.timezone.utc)

    def _truncate_minute(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.replace(second=0, microsecond=0)

    def _gen_id(prefix):
        return f"{prefix}_{hashlib.sha256(f'{prefix}:{_iso(_now_utc())}:{os.urandom(8).hex()}'.encode('utf-8')).hexdigest()[:24]}"

    if not isinstance(search_request_id, str) or not search_request_id.strip():
        return _err("VALIDATION_ERROR", "search_request_id must be a non-empty string")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 25
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100")

    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")
    usage = _load("usage_counters.json")

    api_key = None
    for k in api_keys:
        if k.get("status") == "active":
            api_key = k
            break
    if not api_key:
        return _err("UNAUTHORIZED", "No active API key context available")

    # Rate limiting
    now = _now_utc()
    minute_start = _truncate_minute(now)
    day_start = _truncate_day(now)

    def _find_counter(window_type, window_start):
        for row in usage:
            if row.get("api_key_id") == api_key.get("id") and row.get("window_type") == window_type and row.get("window_start") == _iso(window_start):
                return row
        return None

    minute_row = _find_counter("minute", minute_start)
    day_row = _find_counter("day", day_start)
    minute_count = int(minute_row.get("request_count")) if minute_row else 0
    day_count = int(day_row.get("request_count")) if day_row else 0

    per_minute_limit = int(api_key.get("per_minute_limit", 0))
    daily_limit = int(api_key.get("daily_request_limit", 0))

    if per_minute_limit >= 0 and minute_count >= per_minute_limit:
        return _err("RATE_LIMIT", "Per-minute rate limit exceeded", limit=per_minute_limit, window_type="minute")
    if daily_limit >= 0 and day_count >= daily_limit:
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", limit=daily_limit, window_type="day")

    def _bump_counters(succeeded):
        nonlocal minute_row, day_row
        ts = _iso(now)
        if minute_row is None:
            minute_row = {
                "id": _gen_id("uc"),
                "api_key_id": api_key["id"],
                "window_type": "minute",
                "window_start": _iso(minute_start),
                "request_count": 0,
                "succeeded_count": 0,
                "failed_count": 0,
                "created_at": ts,
                "updated_at": ts,
            }
            usage.append(minute_row)
        if day_row is None:
            day_row = {
                "id": _gen_id("uc"),
                "api_key_id": api_key["id"],
                "window_type": "day",
                "window_start": _iso(day_start),
                "request_count": 0,
                "succeeded_count": 0,
                "failed_count": 0,
                "created_at": ts,
                "updated_at": ts,
            }
            usage.append(day_row)

        minute_row["request_count"] = int(minute_row["request_count"]) + 1
        day_row["request_count"] = int(day_row["request_count"]) + 1
        if succeeded:
            minute_row["succeeded_count"] = int(minute_row["succeeded_count"]) + 1
            day_row["succeeded_count"] = int(day_row["succeeded_count"]) + 1
        else:
            minute_row["failed_count"] = int(minute_row["failed_count"]) + 1
            day_row["failed_count"] = int(day_row["failed_count"]) + 1
        minute_row["updated_at"] = ts
        day_row["updated_at"] = ts
        minute_row["request_count"] = int(minute_row["succeeded_count"]) + int(minute_row["failed_count"])
        day_row["request_count"] = int(day_row["succeeded_count"]) + int(day_row["failed_count"])

    # Ensure request exists and owned by caller
    req = None
    for r in search_requests:
        if r.get("id") == search_request_id and r.get("api_key_id") == api_key.get("id"):
            req = r
            break

    if req is None:
        _bump_counters(succeeded=False)
        _save("usage_counters.json", usage)
        return _err("NOT_FOUND", "Search request not found")

    rows = [sr for sr in search_results if sr.get("search_request_id") == search_request_id]
    rows.sort(key=lambda r: int(r.get("rank") or 0))

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_items = rows[start:end]
    has_more = end < total

    api_key["last_used_at"] = _iso(now)
    api_key["updated_at"] = _iso(now)

    _bump_counters(succeeded=True)
    _save("usage_counters.json", usage)
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": page_items,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
            "search_request_id": search_request_id,
            "api_key_id": api_key.get("id"),
            "latency_ms": latency_ms,
        }
    }

