    if cache_status is not None:
        rows = [c for c in rows if c.get("cache_status") == cache_status]

    # Sort by updated_at desc then pubchem_cid asc for stability
    def _sort_key(c):
        return ((c.get("updated_at") or ""), int(c.get("pubchem_cid") or 0), c.get("id") or "")
